// CSV verisi yoksa (normal collection çalıştırması) bu isteği atla
if (!pm.iterationData.has("firstname")) {
    pm.execution.skipRequest();
}

const json = pm.response.json();
const row = pm.iterationData; // CSV'deki o anki satır

pm.test(`Create booking for ${row.get("firstname")} returns 200`, function () {
    pm.response.to.have.status(200);
});

pm.test(`Booking for ${row.get("firstname")} has a numeric id`, function () {
    pm.expect(json.bookingid).to.be.a("number");
});

pm.test(`Stored data matches CSV row for ${row.get("firstname")}`, function () {
    pm.expect(json.booking.lastname).to.eql(row.get("lastname"));
    pm.expect(String(json.booking.totalprice)).to.eql(String(row.get("totalprice")));
    pm.expect(String(json.booking.depositpaid)).to.eql(String(row.get("depositpaid")));
    pm.expect(json.booking.bookingdates.checkin).to.eql(row.get("checkin"));
});

pm.test("Health check returns 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Response time is under 2000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Login returns 200", function () {
    pm.response.to.have.status(200);
});

const json = pm.response.json();

pm.test("Response contains a token", function () {
    pm.expect(json.token).to.be.a("string").and.not.be.empty;
});

// Chaining: token'ı collection değişkenine kaydet
pm.collectionVariables.set("token", json.token);

const json = pm.response.json();

pm.test("Invalid login does not return a token", function () {
    pm.expect(json).to.not.have.property("token");
});

pm.test("Invalid login returns 'Bad credentials' message", function () {
    pm.expect(json.reason).to.eql("Bad credentials");
});

pm.test("KNOWN BUG: invalid login returns 200 instead of 401", function () {
    pm.response.to.have.status(200);
});

pm.test("KNOWN BUG: missing fields returns 500 instead of 400", function () {
    pm.response.to.have.status(500);
});

pm.test("No booking is created when fields are missing", function () {
    pm.expect(pm.response.text()).to.not.include("bookingid");
});

const json = pm.response.json();

pm.test("KNOWN BUG: negative price is accepted (200 instead of 400)", function () {
    pm.response.to.have.status(200);
});

pm.test("KNOWN BUG: booking is stored with negative totalprice", function () {
    pm.expect(json.booking.totalprice).to.eql(-1);
});

const json = pm.response.json();
const sent = JSON.parse(pm.request.body.raw); // gönderdiğimiz veri

pm.test("KNOWN BUG: create returns 200 instead of 201", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains a numeric bookingid", function () {
    pm.expect(json.bookingid).to.be.a("number");
});

pm.test("Returned booking matches sent data", function () {
    pm.expect(json.booking.firstname).to.eql(sent.firstname);
    pm.expect(json.booking.totalprice).to.eql(sent.totalprice);
    pm.expect(json.booking.bookingdates.checkin).to.eql(sent.bookingdates.checkin);
});

// Chaining: yeni rezervasyonun id'sini kaydet
pm.collectionVariables.set("bookingId", json.bookingid);

const json = pm.response.json();

pm.test("Get booking returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Booking data was persisted correctly", function () {
    pm.expect(json.firstname).to.eql("Sevilay");
    pm.expect(json.lastname).to.eql("Tester");
    pm.expect(json.totalprice).to.eql(150);
    pm.expect(json.depositpaid).to.eql(true);
});

const json = pm.response.json();

pm.test("Update with valid token returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Booking fields were fully updated", function () {
    pm.expect(json.lastname).to.eql("Updated");
    pm.expect(json.totalprice).to.eql(200);
    pm.expect(json.depositpaid).to.eql(false);
    pm.expect(json.bookingdates.checkin).to.eql("2026-12-10");
    pm.expect(json.additionalneeds).to.eql("Dinner");
});

const json = pm.response.json();

pm.test("Partial update returns 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Only the sent fields changed", function () {
    pm.expect(json.firstname).to.eql("Patched");
    pm.expect(json.totalprice).to.eql(250);
});

pm.test("Fields not sent were kept unchanged", function () {
    pm.expect(json.lastname).to.eql("Updated");
    pm.expect(json.additionalneeds).to.eql("Dinner");
    pm.expect(json.bookingdates.checkin).to.eql("2026-12-10");
});

pm.test("Update without token returns 403", function () {
    pm.response.to.have.status(403);
});

pm.test("Response body says 'Forbidden'", function () {
    pm.expect(pm.response.text()).to.eql("Forbidden");
});

pm.test("KNOWN BUG: delete returns 201 instead of 200/204", function () {
    pm.response.to.have.status(201);
});

pm.test("Delete response body is 'Created'", function () {
    pm.expect(pm.response.text()).to.eql("Created");
});

pm.test("Deleted booking returns 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Response body says 'Not Found'", function () {
    pm.expect(pm.response.text()).to.eql("Not Found");
});
